{
  "units": [
    {
      "quote_ref": "F000",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Section title designating 29 CFR 825.110 as governing eligible employees under the FMLA, containing no operative legal rules on its own."
    },
    {
      "quote_ref": "F001:F002",
      "scope_refs": ["F001"],
      "kind": "definition",
      "meaning": "An eligible employee under the FMLA must be an employee of a covered employer who has been employed by the employer for at least 12 months."
    },
    {
      "quote_ref": "F003",
      "scope_refs": ["F001"],
      "kind": "threshold",
      "meaning": "To be an eligible employee of a covered employer under the FMLA, the employee must have been employed for at least 1,250 hours of service during the 12-month period immediately preceding the commencement of the leave, subject to special hours of service requirements for airline flight crew employees under § 825.801."
    },
    {
      "quote_ref": "F004",
      "scope_refs": ["F001"],
      "kind": "threshold",
      "meaning": "To be an eligible employee of a covered employer under the FMLA, the employee must be employed at a worksite where 50 or more employees are employed by the employer within 75 miles of that worksite (referencing § 825.105(b) for employees working outside the U.S.)."
    },
    {
      "quote_ref": "F005",
      "scope_refs": [],
      "kind": "statement",
      "meaning": "The 12 months an employee must have been employed by the employer to be eligible for FMLA leave need not be consecutive months, provided the qualifying conditions of paragraph (b) are met."
    },
    {
      "quote_ref": "F006",
      "scope_refs": ["F005"],
      "kind": "permission",
      "meaning": "In determining whether an employee has been employed by the employer for at least 12 months, employment periods prior to a break in service of seven years or more need not be counted, subject to the exceptions set forth in paragraph (b)(2)."
    },
    {
      "quote_ref": "F007:F008",
      "scope_refs": ["F005", "F007"],
      "kind": "requirement",
      "meaning": "Employment periods preceding a break in service of more than seven years must be counted in determining whether the employee has been employed by the employer for at least 12 months where the employee's break in service is occasioned by the fulfillment of a USERRA-covered service obligation (38 U.S.C. 4301 et seq.); furthermore, the period of absence from work due to or necessitated by USERRA-covered service must also be counted, without providing any greater entitlement than would be available under USERRA."
    },
    {
      "quote_ref": "F007:F009",
      "scope_refs": ["F005", "F007"],
      "kind": "requirement",
      "meaning": "Employment periods preceding a break in service of more than seven years must be counted in determining whether the employee has been employed by the employer for at least 12 months where a written agreement, including a collective bargaining agreement, exists concerning the employer's intention to rehire the employee after the break in service (such as for the employee furthering education or for childrearing purposes)."
    },
    {
      "quote_ref": "F010",
      "scope_refs": ["F005"],
      "kind": "definition",
      "meaning": "If an employee is maintained on the payroll for any part of a week, including any periods of paid or unpaid leave (such as sick or vacation leave) during which other benefits or compensation are provided by the employer (such as workers' compensation or group health plan benefits), that week counts as a full week of employment."
    },
    {
      "quote_ref": "F010",
      "scope_refs": ["F005"],
      "kind": "threshold",
      "meaning": "For the purpose of determining whether intermittent, occasional, or casual employment qualifies as at least 12 months of employment, 52 weeks is deemed to be equal to 12 months."
    },
    {
      "quote_ref": "F011",
      "scope_refs": ["F005"],
      "kind": "permission",
      "meaning": "Employers are not prevented from considering employment prior to a continuous break in service of more than seven years when determining whether an employee has met the 12-month employment requirement."
    },
    {
      "quote_ref": "F011",
      "scope_refs": ["F005"],
      "kind": "condition",
      "meaning": "If an employer chooses to recognize employment prior to a continuous break in service of more than seven years, the employer must do so uniformly with respect to all employees with similar breaks in service."
    },
    {
      "quote_ref": "F012",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "Except as provided in paragraph (c)(2) and § 825.801 for airline flight crew employees, whether an employee has worked the minimum 1,250 hours of service is determined according to FLSA principles for determining compensable hours of work (29 CFR part 785), with the determining factor being the number of hours worked within the meaning of the FLSA, not limited by recordkeeping methods or inaccurate compensation agreements; any accurate accounting of actual hours worked under FLSA principles may be used."
    },
    {
      "quote_ref": "F013",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "An employee returning from USERRA-covered service must be credited with the hours of service that would have been performed but for the absence necessitated by USERRA-covered service when determining FMLA eligibility, adding those hours to any hours actually worked during the previous 12-month period to meet the hours of service requirement (with the pre-service work schedule generally usable for calculations, subject to § 825.801(c) for airline flight crew employees)."
    },
    {
      "quote_ref": "F014",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "If an employer does not maintain an accurate record of hours worked by an employee, including employees exempt from FLSA recordkeeping requirements (such as bona fide executive, administrative, and professional employees under 29 CFR part 541), the employer bears the burden of showing that the employee has not worked the requisite 1,250 hours (for example, by clearly demonstrating that full-time teachers did not work 1,250 hours during the previous 12 months), subject to § 825.801(d) for airline flight crew employees."
    },
    {
      "quote_ref": "F015",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "The determination of whether an employee meets the hours of service requirement and has been employed for a total of at least 12 months must be made as of the date the FMLA leave is to start."
    },
    {
      "quote_ref": "F015",
      "scope_refs": [],
      "kind": "permission",
      "meaning": "An employee may be on non-FMLA leave at the time the 12-month eligibility requirement is met, and in that event, any portion of the leave taken for an FMLA-qualifying reason after meeting the requirement is FMLA leave."
    },
    {
      "quote_ref": "F016",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "Whether 50 employees are employed within 75 miles to determine an employee's FMLA eligibility must be determined at the time the employee gives notice of the need for leave."
    },
    {
      "quote_ref": "F016",
      "scope_refs": [],
      "kind": "prohibition",
      "meaning": "Once an employee is determined eligible in response to notice of the need for leave (whether taken at one time or on an intermittent or reduced leave schedule basis), the employee's eligibility for that specific notice is not affected by any subsequent drop or change in the number of employees within 75 miles of the worksite, and the employer may not terminate employee leave that has already started if the employee count drops below 50."
    },
    {
      "quote_ref": "F016",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "If an employer employs 50 or more employees (such as 60 employees in August) at the time an otherwise eligible employee gives notice of the need for leave, the employer must grant FMLA benefits for leave scheduled to begin later (such as December), even if the employer expects the employee count to drop below 50 (such as to 40 in December) before the leave begins."
    }
  ]
}
